<template><section class="shop-page"><header class="shop-heading"><div><span class="shop-eyebrow">RASTREABILIDADE DA LOJA</span><h1>Histórico de alterações</h1><p>Produtos, notas, dados da loja e transferências entre setores.</p></div><button class="shop-secondary" :disabled="shop.loading" @click="shop.load"><i class="ri-refresh-line"></i> Atualizar</button></header><div v-if="shop.error" class="shop-alert error" role="alert">{{shop.error}}</div><div class="shop-panel"><div class="shop-section-title"><h2>Últimas 100 alterações</h2></div><article v-for="entry in shop.history" :key="entry.id" class="shop-history"><i class="ri-history-line"></i><div><strong>{{actions[entry.action]||entry.action}}<template v-if="entry.after?.name"> · {{entry.after.name}}</template></strong><small>{{entry.actor}} · {{date(entry.created_at)}}</small><div v-if="entry.before" class="shop-diff"><span v-for="change in changes(entry)" :key="change.field">{{change.field}}: <s>{{change.before}}</s> → {{change.after}}</span></div><p v-else-if="entry.action==='NFE_CONFIRMED'">{{entry.after.count}} produto(s) · {{entry.after.supplier}}<br/>Chave: {{entry.after.key}}</p><p v-else-if="entry.action==='CHAT_TRANSFERRED'">Destino: {{entry.after.department_name}} · {{entry.after.reason||'Transferência solicitada pela equipe.'}}</p><p v-else>Cadastro inicial registrado.</p></div></article><div v-if="!shop.history.length" class="shop-empty">As próximas alterações aparecerão aqui.</div></div></section></template>
<script setup>
import { useShopStore } from '@/stores/shop.store'
import { actions,availability,date,money } from '@/utils/shop'
const shop=useShopStore()
function changes(entry){const labels={name:'Nome',sku:'Código',category:'Categoria',unit:'Unidade',barcode:'Código de barras',price_cents:'Preço',availability:'Disponibilidade',description:'Descrição',address:'Endereço',phone:'Telefone',opening_hours:'Horários',active:'Ativo',email:'E-mail',role:'Perfil',department_ids:'Departamentos',is_active:'Acesso ativo',password_changed:'Senha alterada'};const format=(k,v)=>Array.isArray(v)?v.map(id=>shop.departments.find(d=>d.id===id)?.name||'Setor indisponível').join(', ')||'Todos':k==='price_cents'?money(v):k==='availability'?availability[v]:typeof v==='boolean'?(v?'Sim':'Não'):v||'—';return Object.keys(labels).filter(k=>JSON.stringify(entry.before[k])!==JSON.stringify(entry.after[k])).map(k=>({field:labels[k],before:format(k,entry.before[k]),after:format(k,entry.after[k])}))}
</script>
